INSERT INTO "public"."t_english_grammar" VALUES
('egwy0028', U&'\786e\8ba4\591a\4e2a\4e8b\7269\7684\540d\79f0\ff1aAre they + \53ef\6570\540d\8bcd\590d\6570?', U&'\786e\8ba4\591a\4e2a\4e8b\7269\7684\540d\79f0\ff1aAre they + \53ef\6570\540d\8bcd\590d\6570?', U&'["Are they tigers/pandas/elephants? \5b83\4eec\662f\8001\864e/\718a\732b/\5927\8c61\5417\ff1f"]', NULL, U&'\4e09\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.734493', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 1', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.734493', NULL, NULL, NULL, 0),
