('egwy0030', U&'\8be2\95ee\591a\4e2a\4e8b\7269\540d\79f0\ff1aWhat are they? \7b54\8bed They are + \540d\8bcd\590d\6570', U&'\8be2\95ee\591a\4e2a\4e8b\7269\540d\79f0\ff1aWhat are they? \7b54\8bed They are + \540d\8bcd\590d\6570', '["What are they? They are tigers."]', NULL, U&'\4e09\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.737967', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 1', NULL, 3, TIMESTAMP '2026-10-01 23:32:36.737967', NULL, NULL, NULL, 0),
('egwy0031', U&'\4ecb\7ecd\67d0\4eba\ff1aThis is + \4eba\540d', U&'\4ecb\7ecd\67d0\4eba\ff1aThis is + \4eba\540d', U&'["This is Linda. \8fd9\662f\7433\8fbe\3002"]', NULL, U&'\4e09\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.73847', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 1', NULL, 4, TIMESTAMP '2026-10-01 23:32:36.73847', NULL, NULL, NULL, 0),
('egwy0032', U&'\63cf\8ff0\5916\5f62\7279\5f81\ff08\80af\5b9a\ff09\ff1a\4e3b\8bed + have/has got (+a/an/\6570\8bcd)(\5f62\5bb9\8bcd) + \8eab\4f53\90e8\4f4d', U&'\63cf\8ff0\5916\5f62\7279\5f81\ff08\80af\5b9a\ff09\ff1a\4e3b\8bed + have/has got (+a/an/\6570\8bcd)(\5f62\5bb9\8bcd) + \8eab\4f53\90e8\4f4d', '["I have got a nose. / You have got long hair. / He has got two ears."]', NULL, U&'\4e09\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.73881', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 2', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.73881', NULL, NULL, NULL, 0),
('egwy0033', U&'\63cf\8ff0\5916\5f62\7279\5f81\ff08\5426\5b9a\ff09\ff1a\4e3b\8bed + have/has not got ...', U&'\63cf\8ff0\5916\5f62\7279\5f81\ff08\5426\5b9a\ff09\ff1a\4e3b\8bed + have/has not got ...', '["I haven''t got long hair. / He hasn''t got two ears."]', NULL, U&'\4e09\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.73919', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 2', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.73919', NULL, NULL, NULL, 0),
('egwy0034', U&'have got \4e0e has got \7684\533a\522b\ff1aI/you/we/they\7528have got\ff1bhe/she/it\7528has got\ff1bhaven''t got=have not got\ff0chasn''t got=has not got', U&'have got \4e0e has got \7684\533a\522b\ff1aI/you/we/they\7528have got\ff1bhe/she/it\7528has got\ff1bhaven''t got=have not got\ff0chasn''t got=has not got', '["I have got... She has got..."]', NULL, U&'\4e09\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.739628', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 2', NULL, 3, TIMESTAMP '2026-10-01 23:32:36.739628', NULL, NULL, NULL, 0),
('egwy0035', U&'\8868\8fbe\81ea\5df1\559c\6b22/\4e0d\559c\6b22\ff1aI like + \4e8b\7269 / I don''t like + \4e8b\7269', U&'\8868\8fbe\81ea\5df1\559c\6b22/\4e0d\559c\6b22\ff1aI like + \4e8b\7269 / I don''t like + \4e8b\7269', U&'["I like apples. \6211\559c\6b22\82f9\679c\3002/ I don''t like apples. \6211\4e0d\559c\6b22\82f9\679c\3002"]', NULL, U&'\4e09\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.739955', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 3', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.739955', NULL, NULL, NULL, 0),
('egwy0036', U&'\7b2c\4e09\4eba\79f0\5355\6570\8868\559c\597d\ff1a\4e3b\8bed(\4e09\5355) + likes + \4e8b\7269\ff1b\5426\5b9a\7528 doesn''t + like', U&'\7b2c\4e09\4eba\79f0\5355\6570\8868\559c\597d\ff1a\4e3b\8bed(\4e09\5355) + likes + \4e8b\7269\ff1b\5426\5b9a\7528 doesn''t + like', '["He likes apples. / He doesn''t like apples."]', NULL, U&'\4e09\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.740275', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 3', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.740275', NULL, NULL, NULL, 0);             
INSERT INTO "public"."t_english_grammar" VALUES
