('egwy0089', U&'\8be2\95ee\996e\98df\4e60\60ef\ff1aWhat do you eat+\4e09\9910? I eat+\98df\7269.\ff1b\7b2c\4e09\4eba\79f0\7528What does+\4e3b\8bed+eat+\4e09\9910?', U&'\8be2\95ee\996e\98df\4e60\60ef\ff1aWhat do you eat+\4e09\9910? I eat+\98df\7269.\ff1b\7b2c\4e09\4eba\79f0\7528What does+\4e3b\8bed+eat+\4e09\9910?', '["What do you eat for lunch? I eat noodles and meat. / What does Tom eat for breakfast? He eats bread and milk."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.792034', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 1', NULL, 3, TIMESTAMP '2026-10-01 23:32:36.792034', NULL, NULL, NULL, 0),
('egwy0090', U&'\7948\4f7f\53e5\7684\7528\6cd5\ff08\80af\5b9a\5f0f\548c\5426\5b9a\5f0f\ff09\ff1a\80af\5b9a\5f0f\52a8\8bcd\539f\5f62\5f00\5934\ff1b\5426\5b9a\5f0fDon''t+\52a8\8bcd\539f\5f62', U&'\7948\4f7f\53e5\7684\7528\6cd5\ff08\80af\5b9a\5f0f\548c\5426\5b9a\5f0f\ff09\ff1a\80af\5b9a\5f0f\52a8\8bcd\539f\5f62\5f00\5934\ff1b\5426\5b9a\5f0fDon''t+\52a8\8bcd\539f\5f62', '["Plant trees in the park. / Don''t throw it away."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.792322', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 2', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.792322', NULL, NULL, NULL, 0),
('egwy0091', U&'\4e09\4e2aR\539f\5219\ff1aRecycle\ff08\56de\6536\5229\7528\ff09/ Reuse\ff08\518d\4f7f\7528\ff09/ Reduce\ff08\51cf\5c11\4f7f\7528\ff09', U&'\4e09\4e2aR\539f\5219\ff1aRecycle\ff08\56de\6536\5229\7528\ff09/ Reuse\ff08\518d\4f7f\7528\ff09/ Reduce\ff08\51cf\5c11\4f7f\7528\ff09', '["Recycle milk cartons. / Reuse the box as a toy house. / Reduce plastic use."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.792651', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 2', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.792651', NULL, NULL, NULL, 0),
('egwy0092', U&'\8be2\95ee\73af\4fdd\884c\52a8\ff1aWhat can we do to...? \56de\7b54We can+\52a8\8bcd\539f\5f62\ff1bHow do we...? \56de\7b54\5177\4f53\6b65\9aa4', U&'\8be2\95ee\73af\4fdd\884c\52a8\ff1aWhat can we do to...? \56de\7b54We can+\52a8\8bcd\539f\5f62\ff1bHow do we...? \56de\7b54\5177\4f53\6b65\9aa4', '["What can we do to reduce plastic? We can use reusable bags."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.79292', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 2', NULL, 3, TIMESTAMP '2026-10-01 23:32:36.79292', NULL, NULL, NULL, 0),
('egwy0093', U&'\4ecb\7ecd\8282\65e5\65e5\671f\ff1aEarth Day comes on+\65e5\671f\ff1bPeople+\52a8\8bcd\539f\5f62+\6d3b\52a8', U&'\4ecb\7ecd\8282\65e5\65e5\671f\ff1aEarth Day comes on+\65e5\671f\ff1bPeople+\52a8\8bcd\539f\5f62+\6d3b\52a8', '["Earth Day comes on 22 April every year."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.793189', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 2', NULL, 4, TIMESTAMP '2026-10-01 23:32:36.793189', NULL, NULL, NULL, 0);   
INSERT INTO "public"."t_english_grammar" VALUES
('egwy0094', U&'\8fde\8bcdand\ff1a\8fde\63a5\5e76\5217\7684\5355\8bcd\3001\77ed\8bed\6216\53e5\5b50\ff0c\8868\793a\5e76\5217/\987a\627f\5173\7cfb', U&'\8fde\8bcdand\ff1a\8fde\63a5\5e76\5217\7684\5355\8bcd\3001\77ed\8bed\6216\53e5\5b50\ff0c\8868\793a\5e76\5217/\987a\627f\5173\7cfb', '["Tutu and Duoduo are friends. / We read books and play games."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.793441', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 3', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.793441', NULL, NULL, NULL, 0),
('egwy0095', U&'\8fde\8bcdbecause\ff1a\8868\793a\539f\56e0\ff0c\5f15\5bfc\539f\56e0\72b6\8bed\4ece\53e5', U&'\8fde\8bcdbecause\ff1a\8868\793a\539f\56e0\ff0c\5f15\5bfc\539f\56e0\72b6\8bed\4ece\53e5', '["He is funny because he often makes me laugh."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.793828', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 3', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.793828', NULL, NULL, NULL, 0),
('egwy0096', U&'\8fde\8bcdbut\ff1a\8868\793a\8f6c\6298\5173\7cfb\ff0c\8fde\63a5\524d\540e\610f\601d\76f8\53cd\6216\5bf9\6bd4\7684\5185\5bb9', U&'\8fde\8bcdbut\ff1a\8868\793a\8f6c\6298\5173\7cfb\ff0c\8fde\63a5\524d\540e\610f\601d\76f8\53cd\6216\5bf9\6bd4\7684\5185\5bb9', '["I have new friends, but you''re still my friend."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.794108', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 3', NULL, 3, TIMESTAMP '2026-10-01 23:32:36.794108', NULL, NULL, NULL, 0),
('egwy0097', U&'\8c08\8bba\670b\53cb\5f02\540c\ff1a\7528the same/different/similar\63cf\8ff0\670b\53cb\95f4\7684\5171\540c\70b9\548c\4e0d\540c\70b9', U&'\8c08\8bba\670b\53cb\5f02\540c\ff1a\7528the same/different/similar\63cf\8ff0\670b\53cb\95f4\7684\5171\540c\70b9\548c\4e0d\540c\70b9', '["We live in the same street. / We have different hobbies."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.794357', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 3', NULL, 4, TIMESTAMP '2026-10-01 23:32:36.794357', NULL, NULL, NULL, 0),
('egwy0098', U&'\4e00\822c\5c06\6765\65f6be going to\7ed3\6784\ff1a\4e3b\8bed+am/is/are+going to+\52a8\8bcd\539f\5f62\ff0c\8868\793a\8ba1\5212\6216\6253\7b97\505a\67d0\4e8b', U&'\4e00\822c\5c06\6765\65f6be going to\7ed3\6784\ff1a\4e3b\8bed+am/is/are+going to+\52a8\8bcd\539f\5f62\ff0c\8868\793a\8ba1\5212\6216\6253\7b97\505a\67d0\4e8b', '["I''m going to work hard. / She''s going to read more books. / They''re going to exercise more."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.794659', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 4', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.794659', NULL, NULL, NULL, 0),
('egwy0099', U&'be going to\4e5f\53ef\8868\793a\5373\5c06\53d1\751f\7684\4e8b', U&'be going to\4e5f\53ef\8868\793a\5373\5c06\53d1\751f\7684\4e8b', '["We''re going to have the test tomorrow. / Our school''s going to have a basketball team."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.794922', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 4', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.794922', NULL, NULL, NULL, 0),
('egwy0100', U&'\4e00\822c\5c06\6765\65f6will+\52a8\8bcd\539f\5f62\ff1a\4e3b\8bed+will+\52a8\8bcd\539f\5f62+\5176\4ed6\ff0c\63cf\8ff0\672a\6765\53ef\80fd\53d1\751f\7684\4e8b\60c5\6216\8ba1\5212', U&'\4e00\822c\5c06\6765\65f6will+\52a8\8bcd\539f\5f62\ff1a\4e3b\8bed+will+\52a8\8bcd\539f\5f62+\5176\4ed6\ff0c\63cf\8ff0\672a\6765\53ef\80fd\53d1\751f\7684\4e8b\60c5\6216\8ba1\5212', '["People will live on the moon. / Robots will cook for us."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.797605', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 5', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.797605', NULL, NULL, NULL, 0),
('egwy0101', U&'will\7684\4e00\822c\7591\95ee\53e5\ff1aWill+\4e3b\8bed+\52a8\8bcd\539f\5f62\ff1f\80af\5b9a\56de\7b54Yes, \4e3b\8bedwill. \5426\5b9a\56de\7b54No, \4e3b\8bedwon''t.', U&'will\7684\4e00\822c\7591\95ee\53e5\ff1aWill+\4e3b\8bed+\52a8\8bcd\539f\5f62\ff1f\80af\5b9a\56de\7b54Yes, \4e3b\8bedwill. \5426\5b9a\56de\7b54No, \4e3b\8bedwon''t.', '["Will it do homework? No, it won''t."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.798048', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 5', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.798048', NULL, NULL, NULL, 0);           
INSERT INTO "public"."t_english_grammar" VALUES
('egwy0102', U&'\4e00\822c\73b0\5728\65f6\8c08\8bba\8282\65e5\4e60\4fd7\ff1a\4e3b\8bed+\52a8\8bcd\539f\5f62/\52a8\8bcd\7b2c\4e09\4eba\79f0\5355\6570+\5176\4ed6\ff0c\8868\793a\7ecf\5e38\53d1\751f\7684\8282\65e5\6d3b\52a8', U&'\4e00\822c\73b0\5728\65f6\8c08\8bba\8282\65e5\4e60\4fd7\ff1a\4e3b\8bed+\52a8\8bcd\539f\5f62/\52a8\8bcd\7b2c\4e09\4eba\79f0\5355\6570+\5176\4ed6\ff0c\8868\793a\7ecf\5e38\53d1\751f\7684\8282\65e5\6d3b\52a8', '["People eat mooncakes at Mid-Autumn Festival. / He visits his grandparents every Spring Festival."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.798344', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 6', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.798344', NULL, NULL, NULL, 0),
('egwy0103', U&'\4e00\822c\5c06\6765\65f6\8c08\8bba\8282\65e5\8ba1\5212\ff1awill+\52a8\8bcd\539f\5f62\8868\793a\672a\6765\4f1a\53d1\751f\7684\4e8b\ff1bbe going to+\52a8\8bcd\539f\5f62\8868\793a\8ba1\5212\6216\6253\7b97', U&'\4e00\822c\5c06\6765\65f6\8c08\8bba\8282\65e5\8ba1\5212\ff1awill+\52a8\8bcd\539f\5f62\8868\793a\672a\6765\4f1a\53d1\751f\7684\4e8b\ff1bbe going to+\52a8\8bcd\539f\5f62\8868\793a\8ba1\5212\6216\6253\7b97', '["We will have a party tonight. / I''m going to make mooncakes."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.798604', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 6', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.798604', NULL, NULL, NULL, 0),
('egwy0104', U&'\8be2\95ee\8282\65e5\6d3b\52a8\ff1aWhat do you do at...? \95ee\8282\65e5\4e60\4fd7\ff1bWhat are you going to do for...? \95ee\8282\65e5\8ba1\5212', U&'\8be2\95ee\8282\65e5\6d3b\52a8\ff1aWhat do you do at...? \95ee\8282\65e5\4e60\4fd7\ff1bWhat are you going to do for...? \95ee\8282\65e5\8ba1\5212', '["What do you do at the Spring Festival? / What are you going to do for Mid-Autumn Festival?"]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.798995', U&'\5916\7814\7248', U&'\4e0a\518c', 'Unit 6', NULL, 3, TIMESTAMP '2026-10-01 23:32:36.798995', NULL, NULL, NULL, 0),
('egwy0105', U&'be\52a8\8bcd\4e00\822c\8fc7\53bb\5f0f\ff1aam/is\7684\8fc7\53bb\5f0f\4e3awas\ff08\5355\6570\4e3b\8bed\ff09\ff0care\7684\8fc7\53bb\5f0f\4e3awere\ff08\590d\6570/\7b2c\4e8c\4eba\79f0\4e3b\8bed\ff09\ff1b\5426\5b9a\5f62\5f0f\4e3awasn''t/weren''t\3002', U&'be\52a8\8bcd\4e00\822c\8fc7\53bb\5f0f\ff1aam/is\7684\8fc7\53bb\5f0f\4e3awas\ff08\5355\6570\4e3b\8bed\ff09\ff0care\7684\8fc7\53bb\5f0f\4e3awere\ff08\590d\6570/\7b2c\4e8c\4eba\79f0\4e3b\8bed\ff09\ff1b\5426\5b9a\5f62\5f0f\4e3awasn''t/weren''t\3002', '["I was four. They were at the summer camp yesterday."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.802261', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 1', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.802261', NULL, NULL, NULL, 0),
('egwy0106', U&'\60c5\6001\52a8\8bcdcould\7684\8fc7\53bb\5f0f\7528\6cd5\ff1acould\662fcan\7684\8fc7\53bb\5f0f\ff0c\540e\63a5\52a8\8bcd\539f\5f62\ff1b\5426\5b9a\5f62\5f0f\4e3acouldn''t\3002', U&'\60c5\6001\52a8\8bcdcould\7684\8fc7\53bb\5f0f\7528\6cd5\ff1acould\662fcan\7684\8fc7\53bb\5f0f\ff0c\540e\63a5\52a8\8bcd\539f\5f62\ff1b\5426\5b9a\5f62\5f0f\4e3acouldn''t\3002', '["We could play football together. She couldn''t ride a bike before."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.802642', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 1', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.802642', NULL, NULL, NULL, 0),
('egwy0107', U&'\5b9e\4e49\52a8\8bcd\8fc7\53bb\5f0f\ff1a\89c4\5219\52a8\8bcd\52a0-ed\ff08clap\2192clapped, cook\2192cooked, practice\2192practiced, play\2192played, help\2192helped\ff09\ff1b\4e0d\89c4\5219\52a8\8bcd\9700\7279\6b8a\8bb0\5fc6\ff08learn\2192learnt, grow\2192grew, win\2192won, make\2192made, read\2192read\ff09\3002', U&'\5b9e\4e49\52a8\8bcd\8fc7\53bb\5f0f\ff1a\89c4\5219\52a8\8bcd\52a0-ed\ff08clap\2192clapped, cook\2192cooked, practice\2192practiced, play\2192played, help\2192helped\ff09\ff1b\4e0d\89c4\5219\52a8\8bcd\9700\7279\6b8a\8bb0\5fc6\ff08learn\2192learnt, grow\2192grew, win\2192won, make\2192made, read\2192read\ff09\3002', '["We cooked lunch for ourselves. He won the race yesterday."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.802925', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 1', NULL, 3, TIMESTAMP '2026-10-01 23:32:36.802925', NULL, NULL, NULL, 0); 
INSERT INTO "public"."t_english_grammar" VALUES
('egwy0108', U&'\65f6\95f4\903b\8f91\77ed\8bedAt first...By the end of...\ff1aAt first\63a5\8fc7\53bb\521d\671f\72b6\6001/\52a8\4f5c\ff0cBy the end of+\65f6\95f4/\4e8b\4ef6\63a5\8fc7\53bb\6700\7ec8\53d8\5316\ff0c\5747\7528\4e00\822c\8fc7\53bb\65f6\3002', U&'\65f6\95f4\903b\8f91\77ed\8bedAt first...By the end of...\ff1aAt first\63a5\8fc7\53bb\521d\671f\72b6\6001/\52a8\4f5c\ff0cBy the end of+\65f6\95f4/\4e8b\4ef6\63a5\8fc7\53bb\6700\7ec8\53d8\5316\ff0c\5747\7528\4e00\822c\8fc7\53bb\65f6\3002', '["At first, I was nervous. By the end of the camp, I got much better."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.803229', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 1', NULL, 4, TIMESTAMP '2026-10-01 23:32:36.803229', NULL, NULL, NULL, 0),
('egwy0109', U&'\4e00\822c\8fc7\53bb\65f6\52a8\8bcd\53d8\5316\ff1a\89c4\5219\52a8\8bcd\52a0-ed\ff08hurry\2192hurried, help\2192helped, push\2192pushed, clean\2192cleaned, hike\2192hiked\ff09\ff1b\4e0d\89c4\5219\52a8\8bcd\9700\7279\6b8a\8bb0\5fc6\ff08go\2192went, see\2192saw, give\2192gave, speak\2192spoke, meet\2192met, sit\2192sat, bring\2192brought\ff09\3002', U&'\4e00\822c\8fc7\53bb\65f6\52a8\8bcd\53d8\5316\ff1a\89c4\5219\52a8\8bcd\52a0-ed\ff08hurry\2192hurried, help\2192helped, push\2192pushed, clean\2192cleaned, hike\2192hiked\ff09\ff1b\4e0d\89c4\5219\52a8\8bcd\9700\7279\6b8a\8bb0\5fc6\ff08go\2192went, see\2192saw, give\2192gave, speak\2192spoke, meet\2192met, sit\2192sat, bring\2192brought\ff09\3002', '["They hurried up to the top of the hill. He saw some cans and picked them up."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.803515', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 2', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.803515', NULL, NULL, NULL, 0),
('egwy0110', U&'\4e00\822c\8fc7\53bb\65f6\53e5\578b\7ed3\6784\ff1a\9648\8ff0\53e5\ff08\4e3b\8bed+\52a8\8bcd\8fc7\53bb\5f0f+\5176\4ed6\ff09\ff1b\5426\5b9a\53e5\ff08\4e3b\8bed+didn''t+\52a8\8bcd\539f\5f62+\5176\4ed6\ff09\ff1b\7591\95ee\53e5\ff08Did+\4e3b\8bed+\52a8\8bcd\539f\5f62+\5176\4ed6\ff1f\56de\7b54Yes,\4e3b\8bed+did./No,\4e3b\8bed+didn''t.\ff09\3002', U&'\4e00\822c\8fc7\53bb\65f6\53e5\578b\7ed3\6784\ff1a\9648\8ff0\53e5\ff08\4e3b\8bed+\52a8\8bcd\8fc7\53bb\5f0f+\5176\4ed6\ff09\ff1b\5426\5b9a\53e5\ff08\4e3b\8bed+didn''t+\52a8\8bcd\539f\5f62+\5176\4ed6\ff09\ff1b\7591\95ee\53e5\ff08Did+\4e3b\8bed+\52a8\8bcd\539f\5f62+\5176\4ed6\ff1f\56de\7b54Yes,\4e3b\8bed+did./No,\4e3b\8bed+didn''t.\ff09\3002', '["Did you help the elderly cross the street? Yes, I did. / He didn''t hurry to the top."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.803774', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 2', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.803774', NULL, NULL, NULL, 0),
('egwy0111', U&'help sb (to) do sth\53e5\578b\ff1a\4e3b\8bed+helped+\67d0\4eba+\52a8\8bcd\539f\5f62+\5176\4ed6\ff0chelp\540e\63a5\7684\52a8\8bcd\5fc5\987b\7528\539f\5f62\ff08to\53ef\7701\7565\ff09\3002', U&'help sb (to) do sth\53e5\578b\ff1a\4e3b\8bed+helped+\67d0\4eba+\52a8\8bcd\539f\5f62+\5176\4ed6\ff0chelp\540e\63a5\7684\52a8\8bcd\5fc5\987b\7528\539f\5f62\ff08to\53ef\7701\7565\ff09\3002', '["She helped me carry the heavy bag. = She helped me to carry the heavy bag."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.80403', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 2', NULL, 3, TIMESTAMP '2026-10-01 23:32:36.80403', NULL, NULL, NULL, 0),
('egwy0112', U&'can\7684\7528\6cd5\ff1a\8868\80fd\529b\ff08\4e3b\8bed+can/can''t+\52a8\8bcd\539f\5f62\ff09\ff1b\8868\8bf7\6c42/\5efa\8bae\ff08Can I+\52a8\8bcd\539f\5f62...? \56de\7b54\7528Yes,please./No,thanks.\ff09\3002could\662fcan\7684\8fc7\53bb\5f0f\3002', U&'can\7684\7528\6cd5\ff1a\8868\80fd\529b\ff08\4e3b\8bed+can/can''t+\52a8\8bcd\539f\5f62\ff09\ff1b\8868\8bf7\6c42/\5efa\8bae\ff08Can I+\52a8\8bcd\539f\5f62...? \56de\7b54\7528Yes,please./No,thanks.\ff09\3002could\662fcan\7684\8fc7\53bb\5f0f\3002', '["I can help you. Can I help you carry the cart?"]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.804353', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 2', NULL, 4, TIMESTAMP '2026-10-01 23:32:36.804353', NULL, NULL, NULL, 0);          
INSERT INTO "public"."t_english_grammar" VALUES
('egwy0113', U&'Did\5f15\5bfc\7684\4e00\822c\8fc7\53bb\65f6\4e00\822c\7591\95ee\53e5\ff1aDid+\4e3b\8bed+\52a8\8bcd\539f\5f62+\5176\4ed6\ff1f\80af\5b9a\56de\7b54Yes,\4e3b\8bed+did. \5426\5b9a\56de\7b54No,\4e3b\8bed+didn''t. \7b2c\4e09\4eba\79f0\5355\6570\4e5f\7528Did\3002', U&'Did\5f15\5bfc\7684\4e00\822c\8fc7\53bb\65f6\4e00\822c\7591\95ee\53e5\ff1aDid+\4e3b\8bed+\52a8\8bcd\539f\5f62+\5176\4ed6\ff1f\80af\5b9a\56de\7b54Yes,\4e3b\8bed+did. \5426\5b9a\56de\7b54No,\4e3b\8bed+didn''t. \7b2c\4e09\4eba\79f0\5355\6570\4e5f\7528Did\3002', '["Did you like the library? Yes, I did. / Did he read the book? No, he didn''t."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.804604', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 3', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.804604', NULL, NULL, NULL, 0),
('egwy0114', U&'there be\53e5\578b\4e00\822c\8fc7\53bb\65f6\7591\95ee\53e5\ff1aWere there+\540d\8bcd\590d\6570+\5730\70b9/\65f6\95f4\ff1f\56de\7b54Yes,there were./No,there weren''t. \5355\6570/\4e0d\53ef\6570\540d\8bcd\7528Was there...?', U&'there be\53e5\578b\4e00\822c\8fc7\53bb\65f6\7591\95ee\53e5\ff1aWere there+\540d\8bcd\590d\6570+\5730\70b9/\65f6\95f4\ff1f\56de\7b54Yes,there were./No,there weren''t. \5355\6570/\4e0d\53ef\6570\540d\8bcd\7528Was there...?', '["Were there many books? No, there weren''t. / Was there a library in your school before? Yes, there was."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.804849', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 3', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.804849', NULL, NULL, NULL, 0),
('egwy0115', U&'\4e00\822c\8fc7\53bb\65f6\9648\8ff0\53e5\ff1a\63cf\8ff0\8fc7\53bb\53d1\751f\7684\52a8\4f5c\6216\5b58\5728\7684\72b6\6001\ff0c\8c13\8bed\52a8\8bcd\7528\8fc7\53bb\5f0f\3002\65f6\95f4\72b6\8bed\6709yesterday, last week, when I was young, in the past\7b49\3002', U&'\4e00\822c\8fc7\53bb\65f6\9648\8ff0\53e5\ff1a\63cf\8ff0\8fc7\53bb\53d1\751f\7684\52a8\4f5c\6216\5b58\5728\7684\72b6\6001\ff0c\8c13\8bed\52a8\8bcd\7528\8fc7\53bb\5f0f\3002\65f6\95f4\72b6\8bed\6709yesterday, last week, when I was young, in the past\7b49\3002', '["It kept raining. They worked together. Last week, I visited the street library."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.805111', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 3', NULL, 3, TIMESTAMP '2026-10-01 23:32:36.805111', NULL, NULL, NULL, 0),
('egwy0116', U&'\5e76\5217\8fde\8bcdnot only...but also...\ff1a\8868\793a''\4e0d\4ec5\2026\2026\800c\4e14\2026\2026''\ff0c\8fde\63a5\4e24\4e2a\5e76\5217\6210\5206\3002', U&'\5e76\5217\8fde\8bcdnot only...but also...\ff1a\8868\793a''\4e0d\4ec5\2026\2026\800c\4e14\2026\2026''\ff0c\8fde\63a5\4e24\4e2a\5e76\5217\6210\5206\3002', '["Books bring not only joy but also knowledge to children."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.805363', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 3', NULL, 4, TIMESTAMP '2026-10-01 23:32:36.805363', NULL, NULL, NULL, 0),
('egwy0117', U&'\4e00\822c\8fc7\53bb\65f6\7279\6b8a\7591\95ee\53e5\ff1a\5bf9\52a8\4f5c\63d0\95ee\7528 What/How/When+did+\4e3b\8bed+\52a8\8bcd\539f\5f62\ff1f\ff1b\5bf9\72b6\6001\63d0\95ee\7528 Why/How+was/were+\4e3b\8bed\ff1f\3002did\540e\63a5\52a8\8bcd\539f\5f62\ff0cbe\52a8\8bcd\76f4\63a5\7528was/were\3002', U&'\4e00\822c\8fc7\53bb\65f6\7279\6b8a\7591\95ee\53e5\ff1a\5bf9\52a8\4f5c\63d0\95ee\7528 What/How/When+did+\4e3b\8bed+\52a8\8bcd\539f\5f62\ff1f\ff1b\5bf9\72b6\6001\63d0\95ee\7528 Why/How+was/were+\4e3b\8bed\ff1f\3002did\540e\63a5\52a8\8bcd\539f\5f62\ff0cbe\52a8\8bcd\76f4\63a5\7528was/were\3002', '["What did ancient people eat? How did dumplings come to Xinjiang?"]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.805609', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 4', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.805609', NULL, NULL, NULL, 0),
('egwy0118', U&'\4e00\822c\8fc7\53bb\65f6\80af\5b9a\53e5\ff1abe\52a8\8bcd\7528\4e3b\8bed+was/were+\8868\8bed\ff1b\5b9e\4e49\52a8\8bcd\7528\4e3b\8bed+\52a8\8bcd\8fc7\53bb\5f0f\3002\4e0d\89c4\5219\53d8\5316\ff1ago\2192went, do\2192did, bring\2192brought, dig\2192dug, bury\2192buried, see\2192saw, take\2192took\3002', U&'\4e00\822c\8fc7\53bb\65f6\80af\5b9a\53e5\ff1abe\52a8\8bcd\7528\4e3b\8bed+was/were+\8868\8bed\ff1b\5b9e\4e49\52a8\8bcd\7528\4e3b\8bed+\52a8\8bcd\8fc7\53bb\5f0f\3002\4e0d\89c4\5219\53d8\5316\ff1ago\2192went, do\2192did, bring\2192brought, dig\2192dug, bury\2192buried, see\2192saw, take\2192took\3002', '["People found mooncakes in Xinjiang. Pepys dug a hole in his garden."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.805856', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 4', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.805856', NULL, NULL, NULL, 0);        
INSERT INTO "public"."t_english_grammar" VALUES
('egwy0119', U&'\4e00\822c\8fc7\53bb\65f6\4e00\822c\7591\95ee\53e5\ff1a\5b9e\4e49\52a8\8bcd\7528 Did+\4e3b\8bed+\52a8\8bcd\539f\5f62\ff1f\56de\7b54Yes,...did./No,...didn''t.\ff1bbe\52a8\8bcd\7528 Was/Were+\4e3b\8bed\ff1f\56de\7b54Yes,...was/were.', U&'\4e00\822c\8fc7\53bb\65f6\4e00\822c\7591\95ee\53e5\ff1a\5b9e\4e49\52a8\8bcd\7528 Did+\4e3b\8bed+\52a8\8bcd\539f\5f62\ff1f\56de\7b54Yes,...did./No,...didn''t.\ff1bbe\52a8\8bcd\7528 Was/Were+\4e3b\8bed\ff1f\56de\7b54Yes,...was/were.', '["Did people eat mooncakes in the Tang Dynasty? Yes, they did. / Was Xinjiang a trade centre? Yes, it was."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.806109', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 4', NULL, 3, TIMESTAMP '2026-10-01 23:32:36.806109', NULL, NULL, NULL, 0),
('egwy0120', U&'\5b9e\4e49\52a8\8bcd\8fc7\53bb\5f0f\89c4\5219\53d8\5316\ff1a\76f4\63a5\52a0-ed\ff08look\2192looked\ff09\ff1b\4ee5e\7ed3\5c3e\52a0-d\ff08like\2192liked\ff09\ff1b\8f85\97f3+y\53d8i\52a0-ed\ff08study\2192studied\ff09\ff1b\91cd\8bfb\95ed\97f3\8282\53cc\5199\5c3e\5b57\6bcd\52a0-ed\ff08dig\2192dug\ff09\3002', U&'\5b9e\4e49\52a8\8bcd\8fc7\53bb\5f0f\89c4\5219\53d8\5316\ff1a\76f4\63a5\52a0-ed\ff08look\2192looked\ff09\ff1b\4ee5e\7ed3\5c3e\52a0-d\ff08like\2192liked\ff09\ff1b\8f85\97f3+y\53d8i\52a0-ed\ff08study\2192studied\ff09\ff1b\91cd\8bfb\95ed\97f3\8282\53cc\5199\5c3e\5b57\6bcd\52a0-ed\ff08dig\2192dug\ff09\3002', '["He looked at the mirror. She studied history. Pepys dug a hole."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.80649', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 4', NULL, 4, TIMESTAMP '2026-10-01 23:32:36.80649', NULL, NULL, NULL, 0),
('egwy0121', U&'\4e00\822c\8fc7\53bb\65f6\7279\6b8a\7591\95ee\53e5\ff1a\7279\6b8a\7591\95ee\8bcd+did+\4e3b\8bed+\52a8\8bcd\539f\5f62+\5176\4ed6\ff0cdid\4e3a\52a9\52a8\8bcd\540e\63a5\52a8\8bcd\539f\5f62\ff0c\7b54\53e5\7528\4e00\822c\8fc7\53bb\65f6\9648\8ff0\53e5\3002', U&'\4e00\822c\8fc7\53bb\65f6\7279\6b8a\7591\95ee\53e5\ff1a\7279\6b8a\7591\95ee\8bcd+did+\4e3b\8bed+\52a8\8bcd\539f\5f62+\5176\4ed6\ff0cdid\4e3a\52a9\52a8\8bcd\540e\63a5\52a8\8bcd\539f\5f62\ff0c\7b54\53e5\7528\4e00\822c\8fc7\53bb\65f6\9648\8ff0\53e5\3002', '["What did he do? He stole many jewels. / How did she work it out?"]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.806747', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 5', NULL, 1, TIMESTAMP '2026-10-01 23:32:36.806747', NULL, NULL, NULL, 0),
('egwy0122', U&'\5b9e\4e49\52a8\8bcd\4e0d\89c4\5219\8fc7\53bb\5f0f\ff1asteal\2192stole, find\2192found, come\2192came, take\2192took, dig\2192dug\ff0c\4e3b\8bed\4efb\4f55\4eba\79f0\5f62\5f0f\4e0d\53d8\3002', U&'\5b9e\4e49\52a8\8bcd\4e0d\89c4\5219\8fc7\53bb\5f0f\ff1asteal\2192stole, find\2192found, come\2192came, take\2192took, dig\2192dug\ff0c\4e3b\8bed\4efb\4f55\4eba\79f0\5f62\5f0f\4e0d\53d8\3002', '["He stole many jewels. They found the secret in the letter."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.806986', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 5', NULL, 2, TIMESTAMP '2026-10-01 23:32:36.806986', NULL, NULL, NULL, 0),
('egwy0123', U&'use...to...\7528\6cd5\ff1ause+\5de5\5177+to do sth\8868''\7528\2026\2026\505a\67d0\4e8b''\ff1bto do\653e\53e5\672b\8868\76ee\7684''\4e3a\4e86\2026\2026''\ff0c\540e\63a5\52a8\8bcd\539f\5f62\3002', U&'use...to...\7528\6cd5\ff1ause+\5de5\5177+to do sth\8868''\7528\2026\2026\505a\67d0\4e8b''\ff1bto do\653e\53e5\672b\8868\76ee\7684''\4e3a\4e86\2026\2026''\ff0c\540e\63a5\52a8\8bcd\539f\5f62\3002', '["She used some leaves to help. We read the letter to work out the message."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.811388', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 5', NULL, 3, TIMESTAMP '2026-10-01 23:32:36.811388', NULL, NULL, NULL, 0),
('egwy0124', U&'\7948\4f7f\53e5\5426\5b9a\ff1aDon''t+\52a8\8bcd\539f\5f62\ff0c\6784\6210\5426\5b9a\7948\4f7f\53e5\ff0c\8868\793a''\7981\6b62\3001\4e0d\8981\505a\67d0\4e8b''\3002\80af\5b9a\7948\4f7f\53e5\76f4\63a5\4ee5\52a8\8bcd\539f\5f62\5f00\5934\3002', U&'\7948\4f7f\53e5\5426\5b9a\ff1aDon''t+\52a8\8bcd\539f\5f62\ff0c\6784\6210\5426\5b9a\7948\4f7f\53e5\ff0c\8868\793a''\7981\6b62\3001\4e0d\8981\505a\67d0\4e8b''\3002\80af\5b9a\7948\4f7f\53e5\76f4\63a5\4ee5\52a8\8bcd\539f\5f62\5f00\5934\3002', '["Don''t give the letter to his wife. / Give the letter to me."]', NULL, U&'\4e94\5e74\7ea7', TIMESTAMP '2026-10-01 23:32:36.811762', U&'\5916\7814\7248', U&'\4e0b\518c', 'Unit 5', NULL, 4, TIMESTAMP '2026-10-01 23:32:36.811762', NULL, NULL, NULL, 0);
INSERT INTO "public"."t_english_grammar" VALUES
