INSERT INTO "public"."t_english_sentence" VALUES
('eswy0001', 'What''s your name?', U&'\4f60\53eb\4ec0\4e48\540d\5b57\ff1f', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Welcome', 1, TIMESTAMP '2026-10-01 23:32:36.519473', NULL, NULL, NULL, 0, NULL),
('eswy0002', 'My name is Amy!', U&'\6211\7684\540d\5b57\662f\827e\7c73\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Welcome', 2, TIMESTAMP '2026-10-01 23:32:36.520528', NULL, NULL, NULL, 0, NULL),
('eswy0003', 'I''m Lingling.', U&'\6211\662f\73b2\73b2\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Welcome', 3, TIMESTAMP '2026-10-01 23:32:36.52111', NULL, NULL, NULL, 0, NULL),
('eswy0004', 'Good morning!', U&'\65e9\4e0a\597d\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Welcome', 4, TIMESTAMP '2026-10-01 23:32:36.521595', NULL, NULL, NULL, 0, NULL),
('eswy0005', 'Goodbye, Bobo. Have a nice day!', U&'\518d\89c1\ff0c\6ce2\6ce2\3002\795d\4f60\6709\7f8e\597d\7684\4e00\5929\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Welcome', 5, TIMESTAMP '2026-10-01 23:32:36.522087', NULL, NULL, NULL, 0, NULL),
('eswy0006', 'Stand up! / Sit down!', U&'\8d77\7acb\ff01/ \5750\4e0b\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Welcome', 6, TIMESTAMP '2026-10-01 23:32:36.522582', NULL, NULL, NULL, 0, NULL),
('eswy0007', 'Open your book! / Close your book!', U&'\6253\5f00\4f60\4eec\7684\4e66\ff01/ \5408\4e0a\4f60\4eec\7684\4e66\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Welcome', 7, TIMESTAMP '2026-10-01 23:32:36.523053', NULL, NULL, NULL, 0, NULL),
('eswy0008', 'Nice to meet you.', U&'\5f88\9ad8\5174\89c1\5230\4f60\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Welcome', 8, TIMESTAMP '2026-10-01 23:32:36.52354', NULL, NULL, NULL, 0, NULL),
('eswy0009', 'Hi, everyone! I''m Sam. I''m nine.', U&'\55e8\ff0c\5927\5bb6\597d\ff01\6211\662f\8428\59c6\3002\6211\4e5d\5c81\4e86\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 1, TIMESTAMP '2026-10-01 23:32:36.524024', NULL, NULL, NULL, 0, NULL),
('eswy0010', 'She''s Amy. She''s nine, too.', U&'\5979\662f\827e\7c73\3002\5979\4e5f\4e5d\5c81\4e86\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 2, TIMESTAMP '2026-10-01 23:32:36.524612', NULL, NULL, NULL, 0, NULL),
('eswy0011', 'We''re from the UK. We''re twins.', U&'\6211\4eec\6765\81ea\82f1\56fd\3002\6211\4eec\662f\53cc\80de\80ce\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 3, TIMESTAMP '2026-10-01 23:32:36.52507', NULL, NULL, NULL, 0, NULL),
('eswy0012', 'He''s Daming.', U&'\4ed6\662f\5927\660e\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 4, TIMESTAMP '2026-10-01 23:32:36.525522', NULL, NULL, NULL, 0, NULL),
('eswy0013', 'Let''s be friends! Let''s play together!', U&'\8ba9\6211\4eec\6210\4e3a\670b\53cb\5427\ff01\8ba9\6211\4eec\4e00\8d77\73a9\5427\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 5, TIMESTAMP '2026-10-01 23:32:36.525978', NULL, NULL, NULL, 0, NULL),
('eswy0014', 'Nice to meet you.', U&'\5f88\9ad8\5174\89c1\5230\4f60\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 6, TIMESTAMP '2026-10-01 23:32:36.526435', NULL, NULL, NULL, 0, NULL),
('eswy0015', 'Here you are. Thank you.', U&'\7ed9\4f60\3002\8c22\8c22\4f60\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 7, TIMESTAMP '2026-10-01 23:32:36.526883', NULL, NULL, NULL, 0, NULL),
('eswy0016', 'We are friends!', U&'\6211\4eec\662f\670b\53cb\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 8, TIMESTAMP '2026-10-01 23:32:36.527406', NULL, NULL, NULL, 0, NULL),
('eswy0017', 'What''s this? It''s my schoolbag.', U&'\8fd9\662f\4ec0\4e48\ff1f\8fd9\662f\6211\7684\4e66\5305\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 1, TIMESTAMP '2026-10-01 23:32:36.527913', NULL, NULL, NULL, 0, NULL);        
INSERT INTO "public"."t_english_sentence" VALUES
('eswy0018', 'What''s this? It''s a book.', U&'\8fd9\662f\4ec0\4e48\ff1f\8fd9\662f\4e00\672c\4e66\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 2, TIMESTAMP '2026-10-01 23:32:36.528383', NULL, NULL, NULL, 0, NULL),
('eswy0019', 'Is it a pen, too? No, it isn''t. It''s a pencil.', U&'\8fd9\4e5f\662f\4e00\652f\94a2\7b14\5417\ff1f\4e0d\ff0c\4e0d\662f\3002\8fd9\662f\4e00\652f\94c5\7b14\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 3, TIMESTAMP '2026-10-01 23:32:36.528943', NULL, NULL, NULL, 0, NULL),
('eswy0020', 'What''s that, Tom? It''s you, Amy!', U&'\90a3\662f\4ec0\4e48\ff0c\6c64\59c6\ff1f\90a3\662f\4f60\ff0c\827e\7c73\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 4, TIMESTAMP '2026-10-01 23:32:36.529408', NULL, NULL, NULL, 0, NULL),
('eswy0021', 'What''s this? It''s a ruler.', U&'\8fd9\662f\4ec0\4e48\ff1f\8fd9\662f\4e00\628a\5c3a\5b50\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 5, TIMESTAMP '2026-10-01 23:32:36.530078', NULL, NULL, NULL, 0, NULL),
('eswy0022', 'Is it a schoolbag? Yes, it is.', U&'\8fd9\662f\4e00\4e2a\4e66\5305\5417\ff1f\662f\7684\ff0c\5b83\662f\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 6, TIMESTAMP '2026-10-01 23:32:36.530557', NULL, NULL, NULL, 0, NULL),
('eswy0023', 'Pack my bag for school.', U&'\628a\6211\7684\4e66\5305\88c5\597d\53bb\4e0a\5b66\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 7, TIMESTAMP '2026-10-01 23:32:36.531057', NULL, NULL, NULL, 0, NULL),
('eswy0024', 'What colour is it? It''s blue!', U&'\5b83\662f\4ec0\4e48\989c\8272\7684\ff1f\5b83\662f\84dd\8272\7684\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 1, TIMESTAMP '2026-10-01 23:32:36.531541', NULL, NULL, NULL, 0, NULL),
('eswy0025', 'What colours can you see?', U&'\4f60\80fd\770b\5230\4ec0\4e48\989c\8272\ff1f', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 2, TIMESTAMP '2026-10-01 23:32:36.531967', NULL, NULL, NULL, 0, NULL),
('eswy0026', 'I want a balloon!', U&'\6211\60f3\8981\4e00\4e2a\6c14\7403\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 3, TIMESTAMP '2026-10-01 23:32:36.532407', NULL, NULL, NULL, 0, NULL),
('eswy0027', 'Can you guess? It''s red!', U&'\4f60\80fd\731c\5230\5417\ff1f\5b83\662f\7ea2\8272\7684\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 4, TIMESTAMP '2026-10-01 23:32:36.532845', NULL, NULL, NULL, 0, NULL),
('eswy0028', 'Yes! You are right!', U&'\662f\7684\ff01\4f60\662f\5bf9\7684\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 5, TIMESTAMP '2026-10-01 23:32:36.533298', NULL, NULL, NULL, 0, NULL),
('eswy0029', 'It''s yellow! It''s pink! It''s purple!', U&'\5b83\662f\9ec4\8272\7684\ff01\5b83\662f\7c89\8272\7684\ff01\5b83\662f\7d2b\8272\7684\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 6, TIMESTAMP '2026-10-01 23:32:36.533754', NULL, NULL, NULL, 0, NULL),
('eswy0030', 'Look at our umbrellas, look at our clothes.', U&'\770b\770b\6211\4eec\7684\96e8\4f1e\ff0c\770b\770b\6211\4eec\7684\8863\670d\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 7, TIMESTAMP '2026-10-01 23:32:36.534221', NULL, NULL, NULL, 0, NULL),
('eswy0031', 'How many birds can you see?', U&'\4f60\80fd\770b\5230\591a\5c11\53ea\9e1f\ff1f', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 1, TIMESTAMP '2026-10-01 23:32:36.534675', NULL, NULL, NULL, 0, NULL),
('eswy0032', 'One, two, three! Ten, eleven, twelve!', U&'\4e00\ff0c\4e8c\ff0c\4e09\ff01\5341\ff0c\5341\4e00\ff0c\5341\4e8c\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 2, TIMESTAMP '2026-10-01 23:32:36.535334', NULL, NULL, NULL, 0, NULL),
('eswy0033', 'Who can make a Chinese knot?', U&'\8c01\80fd\505a\4e00\4e2a\4e2d\56fd\7ed3\ff1f', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 3, TIMESTAMP '2026-10-01 23:32:36.535806', NULL, NULL, NULL, 0, NULL);  
INSERT INTO "public"."t_english_sentence" VALUES
('eswy0034', 'Wow! What is it? It''s beautiful!', U&'\54c7\ff01\8fd9\662f\4ec0\4e48\ff1f\5b83\5f88\6f02\4eae\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 4, TIMESTAMP '2026-10-01 23:32:36.536263', NULL, NULL, NULL, 0, NULL),
('eswy0035', 'How many ropes? Only one rope!', U&'\6709\591a\5c11\6839\7ef3\5b50\ff1f\53ea\6709\4e00\6839\7ef3\5b50\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 5, TIMESTAMP '2026-10-01 23:32:36.536789', NULL, NULL, NULL, 0, NULL),
('eswy0036', 'That''s amazing!', U&'\592a\795e\5947\4e86\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 6, TIMESTAMP '2026-10-01 23:32:36.53725', NULL, NULL, NULL, 0, NULL),
('eswy0037', 'I see numbers everywhere!', U&'\6211\5230\5904\90fd\80fd\770b\5230\6570\5b57\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 7, TIMESTAMP '2026-10-01 23:32:36.537784', NULL, NULL, NULL, 0, NULL),
('eswy0038', 'Who is that? That is my grandma!', U&'\90a3\662f\8c01\ff1f\90a3\662f\6211\5976\5976\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 1, TIMESTAMP '2026-10-01 23:32:36.538274', NULL, NULL, NULL, 0, NULL),
('eswy0039', 'Sam, this is my dad. Hello!', U&'\8428\59c6\ff0c\8fd9\662f\6211\7238\7238\3002\4f60\597d\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 2, TIMESTAMP '2026-10-01 23:32:36.538795', NULL, NULL, NULL, 0, NULL),
('eswy0040', 'This is my family. We''re a happy family!', U&'\8fd9\662f\6211\7684\5bb6\4eba\3002\6211\4eec\662f\4e00\4e2a\5feb\4e50\7684\4e00\5bb6\4eba\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 3, TIMESTAMP '2026-10-01 23:32:36.539434', NULL, NULL, NULL, 0, NULL),
('eswy0041', 'How many people are in the story?', U&'\6545\4e8b\91cc\6709\591a\5c11\4eba\ff1f', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 4, TIMESTAMP '2026-10-01 23:32:36.5399', NULL, NULL, NULL, 0, NULL),
('eswy0042', 'This is my sister. This is my mum.', U&'\8fd9\662f\6211\59d0\59d0\3002\8fd9\662f\6211\5988\5988\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 5, TIMESTAMP '2026-10-01 23:32:36.540358', NULL, NULL, NULL, 0, NULL),
('eswy0043', 'Come back, Lucky! Don''t worry! We can help!', U&'\56de\6765\ff0c\5e78\8fd0\ff01\522b\62c5\5fc3\ff01\6211\4eec\53ef\4ee5\5e2e\5fd9\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 6, TIMESTAMP '2026-10-01 23:32:36.540959', NULL, NULL, NULL, 0, NULL),
('eswy0044', 'Let''s take a photo together.', U&'\8ba9\6211\4eec\4e00\8d77\62cd\5f20\7167\7247\3002', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 7, TIMESTAMP '2026-10-01 23:32:36.541428', NULL, NULL, NULL, 0, NULL),
('eswy0045', 'Welcome to my new home!', U&'\6b22\8fce\6765\5230\6211\7684\65b0\5bb6\ff01', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 6', 1, TIMESTAMP '2026-10-01 23:32:36.541875', NULL, NULL, NULL, 0, NULL),
('eswy0046', 'Who is in the living room? Who is in the bedroom?', U&'\8c01\5728\5ba2\5385\91cc\ff1f\8c01\5728\5367\5ba4\91cc\ff1f', NULL, U&'\5916\7814\7248', U&'\4e09\5e74\7ea7', U&'\4e0a\518c', 'Unit 6', 2, TIMESTAMP '2026-10-01 23:32:36.542306', NULL, NULL, NULL, 0, NULL),
