('eswy0113', 'Is it cold or hot?', U&'\662f\51b7\8fd8\662f\70ed\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 5, TIMESTAMP '2026-10-01 23:32:36.574533', NULL, NULL, NULL, 0, NULL),
('eswy0114', 'Is it rainy or sunny?', U&'\662f\4e0b\96e8\8fd8\662f\6674\5929\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 6, TIMESTAMP '2026-10-01 23:32:36.575215', NULL, NULL, NULL, 0, NULL),
('eswy0115', 'What''s your favourite season?', U&'\4f60\6700\559c\6b22\7684\5b63\8282\662f\4ec0\4e48\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 1, TIMESTAMP '2026-10-01 23:32:36.575704', NULL, NULL, NULL, 0, NULL),
('eswy0116', 'I like winter best. I can play in the snow.', U&'\6211\6700\559c\6b22\51ac\5929\3002\6211\53ef\4ee5\5728\96ea\5730\91cc\73a9\800d\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 2, TIMESTAMP '2026-10-01 23:32:36.576166', NULL, NULL, NULL, 0, NULL),
('eswy0117', 'I like summer best. I can eat ice cream.', U&'\6211\6700\559c\6b22\590f\5929\3002\6211\53ef\4ee5\5403\51b0\6dc7\6dcb\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 3, TIMESTAMP '2026-10-01 23:32:36.57662', NULL, NULL, NULL, 0, NULL),
('eswy0118', 'What about you, Lingling?', U&'\73b2\73b2\ff0c\4f60\5462\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 4, TIMESTAMP '2026-10-01 23:32:36.577097', NULL, NULL, NULL, 0, NULL),
('eswy0119', 'Why do you also like summer?', U&'\4f60\4e3a\4ec0\4e48\4e5f\559c\6b22\590f\5929\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 5, TIMESTAMP '2026-10-01 23:32:36.577599', NULL, NULL, NULL, 0, NULL),
('eswy0120', 'Because my birthday is in summer!', U&'\56e0\4e3a\6211\7684\751f\65e5\5728\590f\5929\ff01', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 6, TIMESTAMP '2026-10-01 23:32:36.578074', NULL, NULL, NULL, 0, NULL),
('eswy0121', 'Let''s go for a picnic in the park.', U&'\6211\4eec\53bb\516c\56ed\91ce\9910\5427\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 1, TIMESTAMP '2026-10-01 23:32:36.578545', NULL, NULL, NULL, 0, NULL),
('eswy0122', 'How do we get there?', U&'\6211\4eec\600e\4e48\53bb\90a3\513f\5462\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 2, TIMESTAMP '2026-10-01 23:32:36.578969', NULL, NULL, NULL, 0, NULL);           
INSERT INTO "public"."t_english_sentence" VALUES
('eswy0123', 'Let''s go by car! It''s fast!', U&'\6211\4eec\5f00\8f66\53bb\5427\ff01\5f00\8f66\5f88\5feb\ff01', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 3, TIMESTAMP '2026-10-01 23:32:36.579481', NULL, NULL, NULL, 0, NULL),
('eswy0124', 'Let''s meet in five minutes.', U&'\6211\4eec\4e94\5206\949f\540e\89c1\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 4, TIMESTAMP '2026-10-01 23:32:36.579974', NULL, NULL, NULL, 0, NULL),
('eswy0125', 'I go by bike.', U&'\6211\9a91\81ea\884c\8f66\53bb\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 5, TIMESTAMP '2026-10-01 23:32:36.580592', NULL, NULL, NULL, 0, NULL),
('eswy0126', 'She goes by bus.', U&'\5979\5750\516c\4ea4\8f66\53bb\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 6, TIMESTAMP '2026-10-01 23:32:36.581049', NULL, NULL, NULL, 0, NULL),
('eswy0127', 'Where does she go?', U&'\5979\53bb\54ea\513f\4e86\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 6', 1, TIMESTAMP '2026-10-01 23:32:36.581497', NULL, NULL, NULL, 0, NULL),
('eswy0128', 'Susu goes straight on to the museum.', U&'\82cf\82cf\4e00\76f4\8d70\5230\535a\7269\9986\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 6', 2, TIMESTAMP '2026-10-01 23:32:36.581921', NULL, NULL, NULL, 0, NULL),
('eswy0129', 'Then she turns left there.', U&'\7136\540e\5979\5728\90a3\91cc\5de6\8f6c\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 6', 3, TIMESTAMP '2026-10-01 23:32:36.582368', NULL, NULL, NULL, 0, NULL),
('eswy0130', 'At the hospital, she turns right.', U&'\5728\533b\9662\90a3\91cc\53f3\8f6c\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 6', 4, TIMESTAMP '2026-10-01 23:32:36.582815', NULL, NULL, NULL, 0, NULL),
('eswy0131', 'Go straight on to the museum.', U&'\4e00\76f4\8d70\5230\535a\7269\9986\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 6', 5, TIMESTAMP '2026-10-01 23:32:36.583313', NULL, NULL, NULL, 0, NULL),
('eswy0132', 'Be careful!', U&'\5c0f\5fc3\70b9\ff01', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0a\518c', 'Unit 6', 6, TIMESTAMP '2026-10-01 23:32:36.583803', NULL, NULL, NULL, 0, NULL),
('eswy0133', 'What''s your father''s job?', U&'\4f60\7238\7238\7684\5de5\4f5c\662f\4ec0\4e48\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 1', 1, TIMESTAMP '2026-10-01 23:32:36.584286', NULL, NULL, NULL, 0, NULL),
('eswy0134', 'He''s a doctor. He works in a hospital.', U&'\4ed6\662f\4e00\540d\533b\751f\ff0c\4ed6\5728\533b\9662\5de5\4f5c\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 1', 2, TIMESTAMP '2026-10-01 23:32:36.584726', NULL, NULL, NULL, 0, NULL),
('eswy0135', 'What does your mother do?', U&'\4f60\5988\5988\662f\505a\4ec0\4e48\7684\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 1', 3, TIMESTAMP '2026-10-01 23:32:36.585204', NULL, NULL, NULL, 0, NULL),
('eswy0136', 'She''s a nurse. She helps sick people.', U&'\5979\662f\4e00\540d\62a4\58eb\ff0c\5979\5e2e\52a9\751f\75c5\7684\4eba\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 1', 4, TIMESTAMP '2026-10-01 23:32:36.585679', NULL, NULL, NULL, 0, NULL),
('eswy0137', 'Is your uncle a driver?', U&'\4f60\53d4\53d4\662f\53f8\673a\5417\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 1', 5, TIMESTAMP '2026-10-01 23:32:36.586362', NULL, NULL, NULL, 0, NULL),
('eswy0138', 'Where does your aunt work? She works at a school.', U&'\4f60\59d1\59d1\5728\54ea\91cc\5de5\4f5c\ff1f\5979\5728\5b66\6821\5de5\4f5c\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 1', 6, TIMESTAMP '2026-10-01 23:32:36.586841', NULL, NULL, NULL, 0, NULL),
('eswy0139', 'Many people work at night. They brighten the night for others.', U&'\8bb8\591a\4eba\5728\591c\95f4\5de5\4f5c\ff0c\4ed6\4eec\4e3a\522b\4eba\7167\4eae\591c\665a\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 1', 7, TIMESTAMP '2026-10-01 23:32:36.587332', NULL, NULL, NULL, 0, NULL);               
INSERT INTO "public"."t_english_sentence" VALUES
('eswy0140', 'I want to be a police officer when I grow up. I want to protect people.', U&'\6211\957f\5927\540e\60f3\6210\4e3a\4e00\540d\8b66\5bdf\ff0c\6211\60f3\4fdd\62a4\4eba\4eec\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 1', 8, TIMESTAMP '2026-10-01 23:32:36.587816', NULL, NULL, NULL, 0, NULL),
('eswy0141', 'How do you feel today?', U&'\4f60\4eca\5929\611f\89c9\600e\4e48\6837\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 1, TIMESTAMP '2026-10-01 23:32:36.588276', NULL, NULL, NULL, 0, NULL),
('eswy0142', 'I feel sad, because I can''t take part in the Beijing opera show.', U&'\6211\611f\5230\4f24\5fc3\ff0c\56e0\4e3a\6211\4e0d\80fd\53c2\52a0\4eac\5267\8868\6f14\4e86\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 2, TIMESTAMP '2026-10-01 23:32:36.588745', NULL, NULL, NULL, 0, NULL),
('eswy0143', 'Is she coughing? Yes, she is.', U&'\5979\5728\54b3\55fd\5417\ff1f\662f\7684\ff0c\5979\5728\54b3\55fd\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 3, TIMESTAMP '2026-10-01 23:32:36.58925', NULL, NULL, NULL, 0, NULL),
('eswy0144', 'I am feeling better now.', U&'\6211\73b0\5728\611f\89c9\597d\591a\4e86\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 4, TIMESTAMP '2026-10-01 23:32:36.58977', NULL, NULL, NULL, 0, NULL),
('eswy0145', 'We should say sorry when we make a mistake.', U&'\5f53\6211\4eec\72af\9519\65f6\ff0c\6211\4eec\5e94\8be5\9053\6b49\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 5, TIMESTAMP '2026-10-01 23:32:36.590278', NULL, NULL, NULL, 0, NULL),
('eswy0146', 'Jay is very surprised and happy when he gets the new ship model.', U&'\6770\4f0a\6536\5230\65b0\8f6e\8239\6a21\578b\65f6\ff0c\53c8\60ca\559c\53c8\5f00\5fc3\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 6, TIMESTAMP '2026-10-01 23:32:36.590763', NULL, NULL, NULL, 0, NULL),
('eswy0147', 'What makes you happy? Playing with my friends makes me happy.', U&'\4ec0\4e48\8ba9\4f60\611f\5230\9ad8\5174\ff1f\548c\670b\53cb\4eec\4e00\8d77\73a9\8ba9\6211\9ad8\5174\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 7, TIMESTAMP '2026-10-01 23:32:36.591526', NULL, NULL, NULL, 0, NULL),
('eswy0148', 'What are you doing?', U&'\4f60\6b63\5728\505a\4ec0\4e48\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 1, TIMESTAMP '2026-10-01 23:32:36.592013', NULL, NULL, NULL, 0, NULL),
('eswy0149', 'I''m looking at their clothes.', U&'\6211\6b63\5728\770b\4ed6\4eec\7684\8863\670d\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 2, TIMESTAMP '2026-10-01 23:32:36.592457', NULL, NULL, NULL, 0, NULL),
('eswy0150', 'Don''t worry about your clothes. Just go and dance.', U&'\522b\62c5\5fc3\4f60\7684\8863\670d\ff0c\53ea\7ba1\53bb\8df3\821e\5c31\597d\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 3, TIMESTAMP '2026-10-01 23:32:36.592909', NULL, NULL, NULL, 0, NULL),
('eswy0151', 'Is she good at dancing? Yes, she is.', U&'\5979\64c5\957f\8df3\821e\5417\ff1f\662f\7684\ff0c\5979\64c5\957f\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 4, TIMESTAMP '2026-10-01 23:32:36.593428', NULL, NULL, NULL, 0, NULL),
('eswy0152', 'What is the Little Chicken good at? He''s good at singing.', U&'\5c0f\9e21\64c5\957f\4ec0\4e48\ff1f\4ed6\64c5\957f\5531\6b4c\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 5, TIMESTAMP '2026-10-01 23:32:36.593901', NULL, NULL, NULL, 0, NULL),
('eswy0153', 'Why are you crying? Because I''m not good at anything.', U&'\4f60\4e3a\4ec0\4e48\54ed\ff1f\56e0\4e3a\6211\4ec0\4e48\90fd\4e0d\64c5\957f\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 6, TIMESTAMP '2026-10-01 23:32:36.594386', NULL, NULL, NULL, 0, NULL),
('eswy0154', 'He''s teaching me to dance. I can dance very well now.', U&'\4ed6\6b63\5728\6559\6211\8df3\821e\ff0c\6211\73b0\5728\8df3\5f97\5f88\597d\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 7, TIMESTAMP '2026-10-01 23:32:36.594871', NULL, NULL, NULL, 0, NULL);             
INSERT INTO "public"."t_english_sentence" VALUES
('eswy0155', 'What are you doing? We''re digging the earth.', U&'\4f60\4eec\6b63\5728\505a\4ec0\4e48\ff1f\6211\4eec\6b63\5728\6316\6ce5\571f\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 1, TIMESTAMP '2026-10-01 23:32:36.595425', NULL, NULL, NULL, 0, NULL),
('eswy0156', 'Are your seeds growing? Yes, they are.', U&'\4f60\7684\79cd\5b50\5728\751f\957f\5417\ff1f\662f\7684\ff0c\5b83\4eec\5728\751f\957f\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 2, TIMESTAMP '2026-10-01 23:32:36.595904', NULL, NULL, NULL, 0, NULL),
('eswy0157', 'Huahua''s grandpa is a scientist. He works in the fields.', U&'\82b1\82b1\7684\7237\7237\662f\4e00\4f4d\79d1\5b66\5bb6\ff0c\4ed6\5728\7530\5730\91cc\5de5\4f5c\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 3, TIMESTAMP '2026-10-01 23:32:36.596627', NULL, NULL, NULL, 0, NULL),
('eswy0158', 'What do we use plants for? We use plants to make paper.', U&'\6211\4eec\7528\690d\7269\6765\505a\4ec0\4e48\ff1f\6211\4eec\7528\690d\7269\9020\7eb8\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 4, TIMESTAMP '2026-10-01 23:32:36.597124', NULL, NULL, NULL, 0, NULL),
('eswy0159', 'Grandpa has two dreams. He wants to grow tall rice plants with big grains.', U&'\7237\7237\6709\4e24\4e2a\68a6\60f3\ff0c\4ed6\60f3\79cd\51fa\9ad8\4e2a\5b50\3001\8c37\7c92\9971\6ee1\7684\6c34\7a3b\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 5, TIMESTAMP '2026-10-01 23:32:36.59761', NULL, NULL, NULL, 0, NULL),
('eswy0160', 'Why aren''t Sam''s seeds growing? Because those seeds can''t grow.', U&'\8428\59c6\7684\79cd\5b50\4e3a\4ec0\4e48\4e0d\751f\957f\ff1f\56e0\4e3a\90a3\4e9b\79cd\5b50\4e0d\80fd\751f\957f\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 6, TIMESTAMP '2026-10-01 23:32:36.598115', NULL, NULL, NULL, 0, NULL),
('eswy0161', 'What school events do you have?', U&'\4f60\4eec\6709\54ea\4e9b\5b66\6821\6d3b\52a8\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 1, TIMESTAMP '2026-10-01 23:32:36.5986', NULL, NULL, NULL, 0, NULL),
('eswy0162', 'Are there any interesting activities in the Art Festival? Yes, there are.', U&'\827a\672f\8282\6709\6709\8da3\7684\6d3b\52a8\5417\ff1f\662f\7684\ff0c\6709\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 2, TIMESTAMP '2026-10-01 23:32:36.599069', NULL, NULL, NULL, 0, NULL),
('eswy0163', 'What are you doing in the Art Festival, Daming? I''m not drawing. I''m writing Chinese words.', U&'\5927\660e\ff0c\4f60\5728\827a\672f\8282\4e0a\6b63\5728\505a\4ec0\4e48\ff1f\6211\6ca1\5728\753b\753b\ff0c\6211\5728\5199\6c49\5b57\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 3, TIMESTAMP '2026-10-01 23:32:36.599591', NULL, NULL, NULL, 0, NULL),
('eswy0164', 'Where are you going for the field trip? We''re going to a forest.', U&'\4f60\4eec\5b9e\5730\8003\5bdf\8981\53bb\54ea\91cc\ff1f\6211\4eec\8981\53bb\4e00\7247\68ee\6797\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 4, TIMESTAMP '2026-10-01 23:32:36.600087', NULL, NULL, NULL, 0, NULL),
('eswy0165', 'Look! There''s a baby bird. It falls off the tree.', U&'\770b\ff01\6709\4e00\53ea\96cf\9e1f\ff0c\5b83\4ece\6811\4e0a\6389\4e0b\6765\4e86\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 5, TIMESTAMP '2026-10-01 23:32:36.600573', NULL, NULL, NULL, 0, NULL),
('eswy0166', 'We should call the forest keeper to help the baby bird.', U&'\6211\4eec\5e94\8be5\7ed9\68ee\6797\7ba1\7406\5458\6253\7535\8bdd\6765\5e2e\52a9\8fd9\53ea\96cf\9e1f\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 6, TIMESTAMP '2026-10-01 23:32:36.6011', NULL, NULL, NULL, 0, NULL),
