('eswy0169', 'What is Lingling looking for?', U&'\73b2\73b2\5728\627e\4ec0\4e48\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 6', 2, TIMESTAMP '2026-10-01 23:32:36.602888', NULL, NULL, NULL, 0, NULL),
('eswy0170', 'It''s cold outside. You should wear a coat and a scarf.', U&'\5916\9762\5f88\51b7\ff0c\4f60\5e94\8be5\7a7f\4ef6\5916\5957\ff0c\6234\6761\56f4\5dfe\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 6', 3, TIMESTAMP '2026-10-01 23:32:36.603425', NULL, NULL, NULL, 0, NULL),
('eswy0171', 'Can you make clothes from old materials?', U&'\4f60\80fd\7528\65e7\6750\6599\505a\8863\670d\5417\ff1f', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 6', 4, TIMESTAMP '2026-10-01 23:32:36.603901', NULL, NULL, NULL, 0, NULL),
('eswy0172', 'She is making a shirt for the bird.', U&'\5979\6b63\5728\7ed9\5c0f\9e1f\505a\4e00\4ef6\886c\886b\3002', NULL, U&'\5916\7814\7248', U&'\56db\5e74\7ea7', U&'\4e0b\518c', 'Unit 6', 5, TIMESTAMP '2026-10-01 23:32:36.604378', NULL, NULL, NULL, 0, NULL),
