INSERT INTO "public"."t_english_sentence" VALUES
('eswy0184', 'Earth Day comes on 22 April every year.', U&'\5730\7403\65e5\5728\6bcf\5e744\670822\65e5\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 5, TIMESTAMP '2026-10-01 23:32:36.610513', NULL, NULL, NULL, 0, NULL),
('eswy0185', 'They''re places to keep birds warm.', U&'\5b83\4eec\662f\7ed9\9e1f\4fdd\6696\7684\5730\65b9\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 6, TIMESTAMP '2026-10-01 23:32:36.611066', NULL, NULL, NULL, 0, NULL),
('eswy0186', 'Reuse old paper for art homework.', U&'\7528\65e7\7eb8\505a\7f8e\672f\4f5c\4e1a\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 7, TIMESTAMP '2026-10-01 23:32:36.611603', NULL, NULL, NULL, 0, NULL),
('eswy0187', 'Don''t use single-use plastics.', U&'\4e0d\8981\4f7f\7528\4e00\6b21\6027\5851\6599\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 8, TIMESTAMP '2026-10-01 23:32:36.612109', NULL, NULL, NULL, 0, NULL),
('eswy0188', 'Tutu and I live in the same street.', U&'\56fe\56fe\548c\6211\4f4f\5728\540c\4e00\6761\8857\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 1, TIMESTAMP '2026-10-01 23:32:36.612661', NULL, NULL, NULL, 0, NULL),
('eswy0189', 'We play games together and we always have fun.', U&'\6211\4eec\4e00\8d77\73a9\6e38\620f\ff0c\603b\662f\5f88\5f00\5fc3\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 2, TIMESTAMP '2026-10-01 23:32:36.613396', NULL, NULL, NULL, 0, NULL),
('eswy0190', 'I''m unhappy because I''m not your friend now.', U&'\6211\4e0d\5f00\5fc3\ff0c\56e0\4e3a\6211\73b0\5728\4e0d\662f\4f60\7684\670b\53cb\4e86\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 3, TIMESTAMP '2026-10-01 23:32:36.613894', NULL, NULL, NULL, 0, NULL),
('eswy0191', 'He is funny because he often makes me laugh.', U&'\4ed6\5f88\6709\8da3\ff0c\56e0\4e3a\4ed6\7ecf\5e38\8ba9\6211\7b11\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 4, TIMESTAMP '2026-10-01 23:32:36.614402', NULL, NULL, NULL, 0, NULL),
('eswy0192', 'I have new friends, but you''re still my friend.', U&'\6211\6709\65b0\670b\53cb\ff0c\4f46\4f60\4ecd\7136\662f\6211\7684\670b\53cb\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 5, TIMESTAMP '2026-10-01 23:32:36.614883', NULL, NULL, NULL, 0, NULL),
('eswy0193', 'Xiaoxiao and I have different hobbies but we enjoy talking to each other.', U&'\6653\6653\548c\6211\6709\4e0d\540c\7684\7231\597d\ff0c\4f46\6211\4eec\559c\6b22\4e92\76f8\804a\5929\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 6, TIMESTAMP '2026-10-01 23:32:36.615432', NULL, NULL, NULL, 0, NULL),
