('eswy0222', 'By the end of the camp, I got much better.', U&'\5230\590f\4ee4\8425\7ed3\675f\65f6\ff0c\6211\597d\591a\4e86\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 1', 5, TIMESTAMP '2026-10-01 23:32:36.630963', NULL, NULL, NULL, 0, NULL),
('eswy0223', 'He was not a good player.', U&'\4ed6\4e0d\662f\4e00\4e2a\597d\8fd0\52a8\5458\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 1', 6, TIMESTAMP '2026-10-01 23:32:36.635725', NULL, NULL, NULL, 0, NULL),
('eswy0224', 'At first, I couldn''t swim at all.', U&'\8d77\521d\6211\6839\672c\4e0d\4f1a\6e38\6cf3\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 1', 7, TIMESTAMP '2026-10-01 23:32:36.636318', NULL, NULL, NULL, 0, NULL),
('eswy0225', 'They hurried up to the top of the hill.', U&'\4ed6\4eec\5306\5fd9\8d76\5230\5c71\9876\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 1, TIMESTAMP '2026-10-01 23:32:36.636854', NULL, NULL, NULL, 0, NULL),
('eswy0226', 'He didn''t hurry to the top of the hill.', U&'\4ed6\6ca1\6709\5306\5fd9\8d76\5230\5c71\9876\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 2, TIMESTAMP '2026-10-01 23:32:36.637357', NULL, NULL, NULL, 0, NULL),
('eswy0227', 'Did you help the elderly cross the street?', U&'\4f60\5e2e\52a9\8001\4eba\8fc7\9a6c\8def\4e86\5417\ff1f', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 3, TIMESTAMP '2026-10-01 23:32:36.639543', NULL, NULL, NULL, 0, NULL),
('eswy0228', 'She helped me carry the heavy bag.', U&'\5979\5e2e\6211\642c\91cd\5305\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 4, TIMESTAMP '2026-10-01 23:32:36.640145', NULL, NULL, NULL, 0, NULL),
('eswy0229', 'I can help you.', U&'\6211\53ef\4ee5\5e2e\4f60\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 5, TIMESTAMP '2026-10-01 23:32:36.640671', NULL, NULL, NULL, 0, NULL),
('eswy0230', 'Can I help you carry the cart?', U&'\6211\53ef\4ee5\5e2e\4f60\63a8\624b\63a8\8f66\5417\ff1f', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 2', 6, TIMESTAMP '2026-10-01 23:32:36.641189', NULL, NULL, NULL, 0, NULL),
('eswy0231', U&'Did you also have library day then, Mum? \2014Yes, we did.', U&'\5988\5988\ff0c\90a3\65f6\4f60\4e5f\6709\56fe\4e66\9986\65e5\5417\ff1f\2014\662f\7684\ff0c\6211\4eec\6709\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 1, TIMESTAMP '2026-10-01 23:32:36.643728', NULL, NULL, NULL, 0, NULL),
('eswy0232', U&'Were there many books? \2014No, there weren''t.', U&'\6709\5f88\591a\4e66\5417\ff1f\2014\4e0d\ff0c\6ca1\6709\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 2, TIMESTAMP '2026-10-01 23:32:36.644519', NULL, NULL, NULL, 0, NULL);              
INSERT INTO "public"."t_english_sentence" VALUES
('eswy0233', U&'What was the book about? \2014It was about...', U&'\8fd9\672c\4e66\662f\5173\4e8e\4ec0\4e48\7684\ff1f\2014\5b83\662f\5173\4e8e\2026\2026\7684\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 3, TIMESTAMP '2026-10-01 23:32:36.645046', NULL, NULL, NULL, 0, NULL),
('eswy0234', 'It kept raining and raining.', U&'\96e8\4e00\76f4\4e0b\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 4, TIMESTAMP '2026-10-01 23:32:36.647812', NULL, NULL, NULL, 0, NULL),
('eswy0235', 'Her cousin Colin was ill in bed.', U&'\5979\7684\8868\5f1f\79d1\6797\5367\75c5\5728\5e8a\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 5, TIMESTAMP '2026-10-01 23:32:36.64842', NULL, NULL, NULL, 0, NULL),
('eswy0236', 'They worked together to bring the garden back to life.', U&'\4ed6\4eec\4e00\8d77\52aa\529b\8ba9\82b1\56ed\6062\590d\4e86\751f\673a\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 6, TIMESTAMP '2026-10-01 23:32:36.648995', NULL, NULL, NULL, 0, NULL),
('eswy0237', U&'What''s your favourite book? \2014My favourite book is...', U&'\4f60\6700\559c\6b22\7684\4e66\662f\4ec0\4e48\ff1f\2014\6211\6700\559c\6b22\7684\4e66\662f\2026\2026\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 7, TIMESTAMP '2026-10-01 23:32:36.649541', NULL, NULL, NULL, 0, NULL),
('eswy0238', U&'What kind of books do you like best? \2014I like...best.', U&'\4f60\6700\559c\6b22\54ea\79cd\4e66\ff1f\2014\6211\6700\559c\6b22\2026\2026\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 3', 8, TIMESTAMP '2026-10-01 23:32:36.650062', NULL, NULL, NULL, 0, NULL),
('eswy0239', 'What did ancient people put in the dumplings? Nobody knows for sure.', U&'\53e4\4ee3\4eba\5728\997a\5b50\91cc\5305\4e86\4ec0\4e48\ff1f\6ca1\4eba\786e\5207\77e5\9053\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 1, TIMESTAMP '2026-10-01 23:32:36.650591', NULL, NULL, NULL, 0, NULL),
('eswy0240', 'How did dumplings come to Xinjiang? People brought them along the Silk Road.', U&'\997a\5b50\662f\5982\4f55\4f20\5230\65b0\7586\7684\ff1f\4eba\4eec\6cbf\7740\4e1d\7ef8\4e4b\8def\628a\5b83\4eec\5e26\8fc7\53bb\7684\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 2, TIMESTAMP '2026-10-01 23:32:36.65518', NULL, NULL, NULL, 0, NULL),
('eswy0241', 'The dumpling dates back to the Tang Dynasty.', U&'\8fd9\79cd\997a\5b50\53ef\4ee5\8ffd\6eaf\5230\5510\671d\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 3, TIMESTAMP '2026-10-01 23:32:36.655976', NULL, NULL, NULL, 0, NULL),
('eswy0242', 'Pepys dug a hole in his garden.', U&'\4f69\76ae\65af\5728\4ed6\7684\82b1\56ed\91cc\6316\4e86\4e00\4e2a\6d1e\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 4, TIMESTAMP '2026-10-01 23:32:36.656757', NULL, NULL, NULL, 0, NULL),
('eswy0243', 'Did people eat mooncakes in the Tang Dynasty? Yes, they did.', U&'\5510\671d\7684\4eba\4eec\5403\6708\997c\5417\ff1f\662f\7684\ff0c\4ed6\4eec\5403\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 5, TIMESTAMP '2026-10-01 23:32:36.65728', NULL, NULL, NULL, 0, NULL),
('eswy0244', 'Was Xinjiang an important trade centre? Yes, it was.', U&'\65b0\7586\66fe\7ecf\662f\91cd\8981\7684\8d38\6613\4e2d\5fc3\5417\ff1f\662f\7684\ff0c\5b83\662f\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 4', 6, TIMESTAMP '2026-10-01 23:32:36.657779', NULL, NULL, NULL, 0, NULL),
('eswy0245', 'What did he do?', U&'\4ed6\505a\4e86\4ec0\4e48\ff1f', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 1, TIMESTAMP '2026-10-01 23:32:36.658272', NULL, NULL, NULL, 0, NULL),
('eswy0246', 'How did she solve the problem?', U&'\5979\662f\600e\4e48\89e3\51b3\95ee\9898\7684\ff1f', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 2, TIMESTAMP '2026-10-01 23:32:36.65873', NULL, NULL, NULL, 0, NULL);            
INSERT INTO "public"."t_english_sentence" VALUES
('eswy0247', 'He stole many jewels.', U&'\4ed6\5077\4e86\5f88\591a\73e0\5b9d\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 3, TIMESTAMP '2026-10-01 23:32:36.66179', NULL, NULL, NULL, 0, NULL),
('eswy0248', 'Why did he write the letter? He wanted to tell her where the jewels were.', U&'\4ed6\4e3a\4ec0\4e48\5199\4fe1\ff1f\4ed6\60f3\544a\8bc9\5979\73e0\5b9d\5728\54ea\91cc\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 4, TIMESTAMP '2026-10-01 23:32:36.664239', NULL, NULL, NULL, 0, NULL),
('eswy0249', 'We can work out the message.', U&'\6211\4eec\80fd\89e3\5f00\4fe1\606f\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 5, TIMESTAMP '2026-10-01 23:32:36.664839', NULL, NULL, NULL, 0, NULL),
('eswy0250', 'Don''t give the letter to his wife.', U&'\4e0d\8981\628a\4fe1\7ed9\4ed6\7684\59bb\5b50\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 5', 6, TIMESTAMP '2026-10-01 23:32:36.66535', NULL, NULL, NULL, 0, NULL),
('eswy0251', 'We left Beijing in the morning and got to Xi''an in time for lunch.', U&'\6211\4eec\65e9\4e0a\79bb\5f00\5317\4eac\ff0c\53ca\65f6\8d76\5230\897f\5b89\5403\5348\996d\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 6', 1, TIMESTAMP '2026-10-01 23:32:36.665829', NULL, NULL, NULL, 0, NULL),
('eswy0252', 'Grandpa told me the streets of China were full of bikes 30 years ago.', U&'\7237\7237\544a\8bc9\621130\5e74\524d\4e2d\56fd\7684\8857\9053\4e0a\6ee1\662f\81ea\884c\8f66\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 6', 2, TIMESTAMP '2026-10-01 23:32:36.666347', NULL, NULL, NULL, 0, NULL),
('eswy0253', 'Now the streets are still full of bikes, but most are shared bikes.', U&'\73b0\5728\8857\9053\4e0a\4ecd\7136\6ee1\662f\81ea\884c\8f66\ff0c\4f46\5927\591a\6570\662f\5171\4eab\5355\8f66\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 6', 3, TIMESTAMP '2026-10-01 23:32:36.66699', NULL, NULL, NULL, 0, NULL),
('eswy0254', 'He gave up a good life in the city to do something for his hometown.', U&'\4ed6\653e\5f03\4e86\57ce\91cc\7684\7f8e\597d\751f\6d3b\ff0c\4e3a\5bb6\4e61\505a\4e9b\4e8b\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 6', 4, TIMESTAMP '2026-10-01 23:32:36.671278', NULL, NULL, NULL, 0, NULL),
('eswy0255', 'After 22 years, the Daliang Mountains became a green world with over 10 million trees.', U&'22\5e74\540e\ff0c\5927\51c9\5c71\53d8\6210\4e86\62e5\6709\8d85\8fc7\4e00\5343\4e07\68f5\6811\7684\7eff\8272\4e16\754c\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 6', 5, TIMESTAMP '2026-10-01 23:32:36.671879', NULL, NULL, NULL, 0, NULL),
('eswy0256', 'In the past, the journey to school was hard and dangerous.', U&'\8fc7\53bb\ff0c\4e0a\5b66\7684\8def\7a0b\8270\96be\53c8\5371\9669\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 6', 6, TIMESTAMP '2026-10-01 23:32:36.672383', NULL, NULL, NULL, 0, NULL),
('eswy0257', 'Today, there are lots of buildings and roads in my hometown.', U&'\5982\4eca\ff0c\6211\7684\5bb6\4e61\6709\5f88\591a\697c\623f\548c\9053\8def\3002', NULL, U&'\5916\7814\7248', U&'\4e94\5e74\7ea7', U&'\4e0b\518c', 'Unit 6', 7, TIMESTAMP '2026-10-01 23:32:36.672847', NULL, NULL, NULL, 0, NULL),
('eswy0258', 'How much is the robot?', U&'\8fd9\4e2a\673a\5668\4eba\591a\5c11\94b1\ff1f', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 1, TIMESTAMP '2026-10-01 23:32:36.673306', NULL, NULL, NULL, 0, NULL),
('eswy0259', 'It''s 35 yuan. I''ll take it.', U&'35\5143\3002\6211\4e70\4e86\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 2, TIMESTAMP '2026-10-01 23:32:36.673747', NULL, NULL, NULL, 0, NULL),
('eswy0260', 'How much are the cupcakes?', U&'\8fd9\4e9b\7eb8\676f\86cb\7cd5\591a\5c11\94b1\ff1f', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 3, TIMESTAMP '2026-10-01 23:32:36.674211', NULL, NULL, NULL, 0, NULL);
INSERT INTO "public"."t_english_sentence" VALUES
('eswy0261', 'Just remember, gold isn''t everything.', U&'\53ea\8981\8bb0\4f4f\ff0c\91d1\5b50\4e0d\662f\4e07\80fd\7684\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 4, TIMESTAMP '2026-10-01 23:32:36.67465', NULL, NULL, NULL, 0, NULL),
('eswy0262', 'I''ll save my money for the right things from now on.', U&'\4ece\73b0\5728\8d77\ff0c\6211\8981\628a\94b1\5b58\8d77\6765\7528\5728\8be5\7528\7684\5730\65b9\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 5, TIMESTAMP '2026-10-01 23:32:36.679578', NULL, NULL, NULL, 0, NULL),
('eswy0263', 'It''s a good thing for us to share with people in need.', U&'\548c\9700\8981\5e2e\52a9\7684\4eba\5206\4eab\5bf9\6211\4eec\6765\8bf4\662f\4e00\4ef6\597d\4e8b\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 1', 6, TIMESTAMP '2026-10-01 23:32:36.680386', NULL, NULL, NULL, 0, NULL),
('eswy0264', 'Apples are healthier than sweet cakes.', U&'\82f9\679c\6bd4\751c\86cb\7cd5\66f4\5065\5eb7\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 1, TIMESTAMP '2026-10-01 23:32:36.680943', NULL, NULL, NULL, 0, NULL),
('eswy0265', 'Apples without peel taste sweeter.', U&'\5e26\76ae\7684\82f9\679c\5c1d\8d77\6765\66f4\751c\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 2, TIMESTAMP '2026-10-01 23:32:36.681423', NULL, NULL, NULL, 0, NULL),
('eswy0266', 'In my opinion, this book is very interesting.', U&'\5728\6211\770b\6765\ff0c\8fd9\672c\4e66\5f88\6709\8da3\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 3, TIMESTAMP '2026-10-01 23:32:36.681859', NULL, NULL, NULL, 0, NULL),
('eswy0267', 'Why not just eat it?', U&'\4e3a\4ec0\4e48\4e0d\5c31\628a\5b83\5403\4e86\5462\ff1f', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 4, TIMESTAMP '2026-10-01 23:32:36.682298', NULL, NULL, NULL, 0, NULL),
('eswy0268', 'I don''t think so.', U&'\6211\4e0d\8fd9\4e48\8ba4\4e3a\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 5, TIMESTAMP '2026-10-01 23:32:36.682729', NULL, NULL, NULL, 0, NULL),
('eswy0269', 'An apple a day keeps the doctor away.', U&'\4e00\5929\4e00\82f9\679c\ff0c\533b\751f\8fdc\79bb\6211\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 2', 6, TIMESTAMP '2026-10-01 23:32:36.687255', NULL, NULL, NULL, 0, NULL),
('eswy0270', 'Mount Qomolangma is the world''s highest mountain.', U&'\73e0\7a46\6717\739b\5cf0\662f\4e16\754c\4e0a\6700\9ad8\7684\5c71\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 1, TIMESTAMP '2026-10-01 23:32:36.688018', NULL, NULL, NULL, 0, NULL),
('eswy0271', 'The longest river in the world is the Nile.', U&'\4e16\754c\4e0a\6700\957f\7684\6cb3\662f\5c3c\7f57\6cb3\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 2, TIMESTAMP '2026-10-01 23:32:36.688496', NULL, NULL, NULL, 0, NULL),
('eswy0272', 'How high is it? It was 8848.86 metres high in 2020.', U&'\5b83\6709\591a\9ad8\ff1f2020\5e74\65f6\5b83\9ad88848.86\7c73\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 3, TIMESTAMP '2026-10-01 23:32:36.689121', NULL, NULL, NULL, 0, NULL),
('eswy0273', 'There''re so many wonders on earth.', U&'\5730\7403\4e0a\6709\5f88\591a\81ea\7136\5947\89c2\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 4, TIMESTAMP '2026-10-01 23:32:36.68957', NULL, NULL, NULL, 0, NULL),
('eswy0274', 'Xu Xiake is one of the most famous travellers in China.', U&'\5f90\971e\5ba2\662f\4e2d\56fd\6700\8457\540d\7684\65c5\884c\5bb6\4e4b\4e00\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 5, TIMESTAMP '2026-10-01 23:32:36.690009', NULL, NULL, NULL, 0, NULL),
('eswy0275', 'Colourful nature brings us joy and delight.', U&'\591a\5f69\7684\5927\81ea\7136\7ed9\6211\4eec\5e26\6765\6b22\4e50\548c\559c\60a6\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 3', 6, TIMESTAMP '2026-10-01 23:32:36.690477', NULL, NULL, NULL, 0, NULL);              
INSERT INTO "public"."t_english_sentence" VALUES
('eswy0276', 'First, make a small hole in the middle of the bottle top.', U&'\9996\5148\ff0c\5728\74f6\76d6\4e2d\95f4\94bb\4e00\4e2a\5c0f\6d1e\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 1, TIMESTAMP '2026-10-01 23:32:36.690901', NULL, NULL, NULL, 0, NULL),
('eswy0277', 'Next, cut off the bottom. Then, put water in the bottle.', U&'\63a5\7740\ff0c\526a\6389\5e95\90e8\3002\7136\540e\ff0c\5f80\74f6\5b50\91cc\88c5\6c34\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 2, TIMESTAMP '2026-10-01 23:32:36.695694', NULL, NULL, NULL, 0, NULL),
('eswy0278', 'Finally, put it in the pot.', U&'\6700\540e\ff0c\628a\5b83\653e\8fdb\82b1\76c6\91cc\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 3, TIMESTAMP '2026-10-01 23:32:36.696273', NULL, NULL, NULL, 0, NULL),
('eswy0279', 'What are you doing? I''m making a watering bottle for the plants.', U&'\4f60\5728\505a\4ec0\4e48\ff1f\6211\5728\7ed9\690d\7269\505a\4e00\4e2a\6d47\6c34\58f6\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 4, TIMESTAMP '2026-10-01 23:32:36.696752', NULL, NULL, NULL, 0, NULL),
('eswy0280', 'Use our minds and our hands to make trash into treasure.', U&'\7528\6211\4eec\7684\5934\8111\548c\53cc\624b\53d8\5e9f\4e3a\5b9d\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 5, TIMESTAMP '2026-10-01 23:32:36.697186', NULL, NULL, NULL, 0, NULL),
('eswy0281', 'You can do anything if you try your best.', U&'\53ea\8981\5c3d\529b\ff0c\4f60\5c31\80fd\505a\6210\4efb\4f55\4e8b\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 4', 6, TIMESTAMP '2026-10-01 23:32:36.697821', NULL, NULL, NULL, 0, NULL),
('eswy0282', 'What''s the matter? I have a fever and a bad headache.', U&'\600e\4e48\4e86\ff1f\6211\53d1\70e7\800c\4e14\5934\75db\5f97\5389\5bb3\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 1, TIMESTAMP '2026-10-01 23:32:36.698281', NULL, NULL, NULL, 0, NULL),
('eswy0283', 'You should take this medicine and get lots of sleep.', U&'\4f60\5e94\8be5\5403\4e0b\8fd9\4e2a\836f\5e76\591a\7761\89c9\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 2, TIMESTAMP '2026-10-01 23:32:36.698685', NULL, NULL, NULL, 0, NULL),
('eswy0284', 'You should not read in the dark.', U&'\4f60\4e0d\5e94\8be5\5728\9ed1\6697\4e2d\770b\4e66\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 3, TIMESTAMP '2026-10-01 23:32:36.699112', NULL, NULL, NULL, 0, NULL),
('eswy0285', 'Eat healthy food and do sports, then you''ll be healthy and strong.', U&'\5403\5065\5eb7\7684\98df\7269\ff0c\591a\8fd0\52a8\ff0c\8fd9\6837\4f60\5c31\4f1a\5065\5eb7\5f3a\58ee\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 4, TIMESTAMP '2026-10-01 23:32:36.703893', NULL, NULL, NULL, 0, NULL),
('eswy0286', 'Just put a smile on your face and gladly face your day.', U&'\9762\5e26\5fae\7b11\ff0c\5f00\5fc3\5730\9762\5bf9\6bcf\4e00\5929\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 5, TIMESTAMP '2026-10-01 23:32:36.704777', NULL, NULL, NULL, 0, NULL),
('eswy0287', 'Be kind to others, and it will bring you happiness.', U&'\5584\5f85\4ed6\4eba\ff0c\8fd9\4f1a\7ed9\4f60\5e26\6765\5feb\4e50\3002', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 5', 6, TIMESTAMP '2026-10-01 23:32:36.705266', NULL, NULL, NULL, 0, NULL),
('eswy0288', 'What a cute panda!', U&'\591a\53ef\7231\7684\718a\732b\554a\ff01', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 6', 1, TIMESTAMP '2026-10-01 23:32:36.705685', NULL, NULL, NULL, 0, NULL),
('eswy0289', 'What a beautiful place it is!', U&'\591a\4e48\7f8e\4e3d\7684\5730\65b9\554a\ff01', NULL, U&'\5916\7814\7248', U&'\516d\5e74\7ea7', U&'\4e0a\518c', 'Unit 6', 2, TIMESTAMP '2026-10-01 23:32:36.706103', NULL, NULL, NULL, 0, NULL),
